-- Normalize contaminated stableIds: replace base64url chars (- and _) with clean alphanumeric IDs.
-- Generated by crux/scripts/normalize-stableids.ts on 2026-03-26.
-- 85 stableIds to normalize.
-- See crux/scripts/stableid-migration-map.json for the full old→new mapping.
--
-- REQUIRES: superuser or REPLICATION role (for SET session_replication_role).
-- Run with: psql "$DATABASE_MIGRATION_URL" -f apps/wiki-server/scripts/0141-normalize-stableids.sql
--
-- Strategy: disable FK triggers via session_replication_role, update all tables,
-- re-enable triggers. This is a manual migration because the standard Drizzle
-- migration runner may not have superuser permissions.
--
-- Verify after applying:
--   SELECT stable_id FROM entities WHERE stable_id ~ '[-_]';
--   -- Should return 0 rows.

CREATE TEMP TABLE stableid_migration (
  old_id TEXT PRIMARY KEY,
  new_id TEXT NOT NULL UNIQUE
);

