-- Temporarily disable FK constraint checking
SET session_replication_role = replica;

-- Wrap all updates in a transaction for atomicity
BEGIN;

-- ── FactBase ────────────────────────────────────────────────────────────

-- summaries: entity_id FK -> entities.stable_id
UPDATE summaries t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- facts: entity_id FK + subject FK -> entities.stable_id
UPDATE facts t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;
UPDATE facts t SET subject = m.new_id FROM stableid_migration m WHERE t.subject = m.old_id;

-- ── PG-primary relational tables ────────────────────────────────────────

-- personnel: person_entity_id, org_entity_id (FK), person_id, organization_id (legacy text)
UPDATE personnel t SET person_entity_id = m.new_id FROM stableid_migration m WHERE t.person_entity_id = m.old_id;
UPDATE personnel t SET org_entity_id = m.new_id FROM stableid_migration m WHERE t.org_entity_id = m.old_id;
UPDATE personnel t SET person_id = m.new_id FROM stableid_migration m WHERE t.person_id = m.old_id;
UPDATE personnel t SET organization_id = m.new_id FROM stableid_migration m WHERE t.organization_id = m.old_id;

-- grants: org_entity_id, grantee_entity_id (FK), organization_id, grantee_id (legacy text)
UPDATE grants t SET org_entity_id = m.new_id FROM stableid_migration m WHERE t.org_entity_id = m.old_id;
UPDATE grants t SET grantee_entity_id = m.new_id FROM stableid_migration m WHERE t.grantee_entity_id = m.old_id;
UPDATE grants t SET grantee_id = m.new_id FROM stableid_migration m WHERE t.grantee_id = m.old_id;
UPDATE grants t SET organization_id = m.new_id FROM stableid_migration m WHERE t.organization_id = m.old_id;

-- funding_rounds: company_entity_id, lead_investor_entity_id (FK), company_id, lead_investor (legacy text)
UPDATE funding_rounds t SET company_entity_id = m.new_id FROM stableid_migration m WHERE t.company_entity_id = m.old_id;
UPDATE funding_rounds t SET lead_investor_entity_id = m.new_id FROM stableid_migration m WHERE t.lead_investor_entity_id = m.old_id;
UPDATE funding_rounds t SET company_id = m.new_id FROM stableid_migration m WHERE t.company_id = m.old_id;
UPDATE funding_rounds t SET lead_investor = m.new_id FROM stableid_migration m WHERE t.lead_investor = m.old_id;

-- investments: company_entity_id, investor_entity_id (FK), company_id, investor_id (legacy text)
UPDATE investments t SET company_entity_id = m.new_id FROM stableid_migration m WHERE t.company_entity_id = m.old_id;
UPDATE investments t SET investor_entity_id = m.new_id FROM stableid_migration m WHERE t.investor_entity_id = m.old_id;
UPDATE investments t SET company_id = m.new_id FROM stableid_migration m WHERE t.company_id = m.old_id;
UPDATE investments t SET investor_id = m.new_id FROM stableid_migration m WHERE t.investor_id = m.old_id;

-- equity_positions: company_entity_id, holder_entity_id (FK), company_id, holder_id (legacy text)
UPDATE equity_positions t SET company_entity_id = m.new_id FROM stableid_migration m WHERE t.company_entity_id = m.old_id;
UPDATE equity_positions t SET holder_entity_id = m.new_id FROM stableid_migration m WHERE t.holder_entity_id = m.old_id;
UPDATE equity_positions t SET company_id = m.new_id FROM stableid_migration m WHERE t.company_id = m.old_id;
UPDATE equity_positions t SET holder_id = m.new_id FROM stableid_migration m WHERE t.holder_id = m.old_id;

-- secondary_market_prices: company_entity_id FK -> entities.stable_id
UPDATE secondary_market_prices t SET company_entity_id = m.new_id FROM stableid_migration m WHERE t.company_entity_id = m.old_id;

-- divisions: parent_org_id FK -> entities.stable_id
UPDATE divisions t SET parent_org_id = m.new_id FROM stableid_migration m WHERE t.parent_org_id = m.old_id;

-- division_personnel: person_id FK -> entities.stable_id
UPDATE division_personnel t SET person_id = m.new_id FROM stableid_migration m WHERE t.person_id = m.old_id;

-- benchmark_results: model_id FK -> entities.stable_id
UPDATE benchmark_results t SET model_id = m.new_id FROM stableid_migration m WHERE t.model_id = m.old_id;

-- funding_programs: org_id (text, stores stableId)
UPDATE funding_programs t SET org_id = m.new_id FROM stableid_migration m WHERE t.org_id = m.old_id;

-- entity_events: entity_id FK -> entities.stable_id
UPDATE entity_events t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- entity_assessments: entity_id FK -> entities.stable_id
UPDATE entity_assessments t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- publications: entity_id FK -> entities.stable_id
UPDATE publications t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- entity_recommended_resources: entity_id FK -> entities.stable_id
UPDATE entity_recommended_resources t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- ── Policy & political tables ───────────────────────────────────────────

-- policy_stakeholders: policy_entity_id, stakeholder_entity_id FK -> entities.stable_id
UPDATE policy_stakeholders t SET policy_entity_id = m.new_id FROM stableid_migration m WHERE t.policy_entity_id = m.old_id;
UPDATE policy_stakeholders t SET stakeholder_entity_id = m.new_id FROM stableid_migration m WHERE t.stakeholder_entity_id = m.old_id;

-- political_races: policy_entity_id FK -> entities.stable_id
UPDATE political_races t SET policy_entity_id = m.new_id FROM stableid_migration m WHERE t.policy_entity_id = m.old_id;

-- race_candidates: candidate_entity_id, pac_entity_id FK -> entities.stable_id
UPDATE race_candidates t SET candidate_entity_id = m.new_id FROM stableid_migration m WHERE t.candidate_entity_id = m.old_id;
UPDATE race_candidates t SET pac_entity_id = m.new_id FROM stableid_migration m WHERE t.pac_entity_id = m.old_id;

-- ── Prediction markets ──────────────────────────────────────────────────

-- prediction_market_questions: entity_id FK -> entities.stable_id
UPDATE prediction_market_questions t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- ── Website & social media sources ──────────────────────────────────────

-- website_sources: entity_id FK -> entities.stable_id
UPDATE website_sources t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- bluesky_accounts: entity_stable_id FK -> entities.stable_id
UPDATE bluesky_accounts t SET entity_stable_id = m.new_id FROM stableid_migration m WHERE t.entity_stable_id = m.old_id;

-- ── Source-check system ─────────────────────────────────────────────────

-- source_check_evidence: entity_id (text, stores stableId for grouping)
UPDATE source_check_evidence t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- source_check_verdicts: entity_id (text, stores stableId for grouping)
UPDATE source_check_verdicts t SET entity_id = m.new_id FROM stableid_migration m WHERE t.entity_id = m.old_id;

-- ── Resources ───────────────────────────────────────────────────────────

-- resources: publisher_entity_id (text, stores stableId)
UPDATE resources t SET publisher_entity_id = m.new_id FROM stableid_migration m WHERE t.publisher_entity_id = m.old_id;

-- resource_policy_docs: jurisdiction_entity_id, agency_entity_id, policy_entity_id (text, may store stableIds)
UPDATE resource_policy_docs t SET jurisdiction_entity_id = m.new_id FROM stableid_migration m WHERE t.jurisdiction_entity_id = m.old_id;
UPDATE resource_policy_docs t SET agency_entity_id = m.new_id FROM stableid_migration m WHERE t.agency_entity_id = m.old_id;
UPDATE resource_policy_docs t SET policy_entity_id = m.new_id FROM stableid_migration m WHERE t.policy_entity_id = m.old_id;

-- ── Research areas ──────────────────────────────────────────────────────

-- research_area_organizations: organization_id (text, may store stableId or slug)
UPDATE research_area_organizations t SET organization_id = m.new_id FROM stableid_migration m WHERE t.organization_id = m.old_id;

-- ── Agent / operational tables ──────────────────────────────────────────

-- agent_session_entities: entity_stable_id (text, stores stableId)
UPDATE agent_session_entities t SET entity_stable_id = m.new_id FROM stableid_migration m WHERE t.entity_stable_id = m.old_id;

-- ── Cross-base things table ─────────────────────────────────────────────

-- things: id (PK, stores stableId for entity-type things),
--         source_id (stores stableId when source_table='entities'),
--         parent_thing_id (may reference an entity-type thing id)
UPDATE things t SET id = m.new_id FROM stableid_migration m WHERE t.id = m.old_id;
UPDATE things t SET source_id = m.new_id FROM stableid_migration m WHERE t.source_id = m.old_id;
UPDATE things t SET parent_thing_id = m.new_id FROM stableid_migration m WHERE t.parent_thing_id = m.old_id;

-- qa_page_checks: thing_id FK -> things.id (which stores stableId for entity things)
UPDATE qa_page_checks t SET thing_id = m.new_id FROM stableid_migration m WHERE t.thing_id = m.old_id;

-- Note: JSONB array columns (resources.author_entity_ids, resources.related_entity_ids,
-- bluesky_posts.entity_stable_ids) are not updated here because:
-- 1. They are rebuilt from YAML on every build-data sync
-- 2. Updating JSONB arrays requires more complex SQL and is not worth the risk
-- The next build-data run will produce clean values from the updated YAML.

-- ── Primary tables (updated LAST so child FK refs are already migrated) ──

-- entity_ids registry (stable_id column)
UPDATE entity_ids t SET stable_id = m.new_id FROM stableid_migration m WHERE t.stable_id = m.old_id;

-- entities PK (stable_id is the primary key) — must be last
UPDATE entities e SET stable_id = m.new_id FROM stableid_migration m WHERE e.stable_id = m.old_id;

COMMIT;

-- Re-enable FK constraint checking
SET session_replication_role = DEFAULT;

DROP TABLE stableid_migration;
